<script setup>
import { ref,computed } from 'vue'
import { useRouter } from 'vue-router'
import { ShieldCheck,Info,Wallet } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import LedgerTable from '../components/LedgerTable.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { state,money,stamp,uid } from '../lib/store'
import { requireRole,confirm,notify } from '../lib/actions'
const router=useRouter(),tab=ref('flows'),amount=ref(1000),bankDialog=ref(false),amountInput=ref(null)
const today=()=>new Date().toLocaleDateString('sv-SE'),doneToday=computed(()=>state.withdrawals.some(w=>w.day===today())),withdrawForm=ref(null)
function bind(){if(!requireRole(router,'creator',true))return;bankDialog.value=true}
async function withdraw(){if(!requireRole(router,'creator',true))return;const cents=Math.round(Number(amount.value)*100);if(!state.bankBound){ElMessage.warning('请先绑定演示银行卡');return}if(!Number.isFinite(cents)||cents<10000||cents>state.balance){ElMessage.warning('提现金额须不低于 ¥100 且不超过可提现余额');return}if(doneToday.value){ElMessage.warning('每天仅可申请 1 笔提现');return}if(!(await confirm(`模拟提现 ¥${money(cents)} 至演示银行卡（尾号 1234），不会真实打款。`,'确认演示提现')))return;state.balance-=cents;state.frozen+=cents;const w={id:uid('W'),at:stamp(),day:today(),cents,status:'审核中',bank:'演示银行卡（尾号1234）'};state.withdrawals.unshift(w);state.flows.unshift({id:uid('F'),at:w.at,type:'提现',title:'提现至演示银行卡',cents:-cents,status:'审核中'});notify('演示提现申请已保存，余额已转为冻结中');tab.value='withdrawals'}
</script>
<template><div><PageTitle title="我的钱包" description="创作有回报，每一笔收入都有记录。"/><div class="wallet-banner"><img src="/assets/task-square/chrome-banner.webp" alt=""/><div><span>可提现余额</span><strong class="wallet-amount">¥{{money(state.balance)}}</strong></div><el-button @click="withdrawForm?.scrollIntoView({behavior:'smooth'});amountInput?.focus()">申请提现</el-button><div><span>冻结中</span><strong>¥{{money(state.frozen)}}</strong></div><div><span>累计收入</span><strong>¥{{money(state.earned)}}</strong></div></div><div class="columns wallet-columns"><section class="panel"><el-tabs v-model="tab"><el-tab-pane label="资金流水" name="flows"/><el-tab-pane label="提现记录" name="withdrawals"/></el-tabs><LedgerTable v-if="tab==='flows'" :rows="state.flows"/><el-table v-else :data="state.withdrawals"><el-table-column prop="at" label="申请时间" width="150"/><el-table-column label="提现金额" width="120"><template #default="{row}">¥{{money(row.cents)}}</template></el-table-column><el-table-column prop="bank" label="收款银行卡" min-width="160"/><el-table-column label="状态" width="100"><template #default="{row}"><StatusBadge :status="row.status"/></template></el-table-column><template #empty><el-empty description="还没有提现申请" :image-size="75"/></template></el-table></section><section ref="withdrawForm" class="panel"><h2>申请提现</h2><div class="info-note" :class="{'success':state.auth.personal==='演示已认证'&&state.bankBound}"><ShieldCheck/>{{state.auth.personal==='演示已认证'&&state.bankBound?'演示实名与银行卡状态已通过':'提现前需完成实名认证与银行卡绑定'}}</div><el-form label-position="top" style="margin-top:20px"><el-form-item label="绑定银行卡"><el-input :model-value="state.bankBound?'演示银行卡（尾号1234）':'尚未绑定演示银行卡'" readonly><template #append><el-button @click="bind">{{state.bankBound?'管理':'绑定'}}</el-button></template></el-input></el-form-item><el-form-item label="提现金额（元）"><el-input-number ref="amountInput" v-model="amount" :min="0" :max="state.balance/100" :precision="2" :controls="false"/><el-button link type="primary" @click="amount=state.balance/100">全部提现</el-button></el-form-item><div class="info-note"><Info/>最低 ¥100 / 每日 1 笔 / T+1 工作日到账 / 手续费平台承担。当前演示不会真实打款。</div><el-button type="primary" class="full-button" style="margin-top:22px" :disabled="doneToday||state.balance<10000" @click="withdraw">{{doneToday?'今日已申请提现':'确认提现（演示）'}}</el-button></el-form><p class="field-help" style="margin-top:22px">新账号首单可能延迟 24 小时并复核。冻结金额不计入可提现余额。</p></section></div><el-dialog v-model="bankDialog" title="演示银行卡绑定" width="440px" class="refinement-dialog"><div class="app-ui dialog-stack"><Wallet :size="36"/><p>用于体验提现流程，不采集真实姓名、卡号或银行信息。</p><div class="info-note">演示储蓄卡 · 尾号 1234</div></div><template #footer><el-button @click="bankDialog=false">取消</el-button><el-button type="primary" @click="state.bankBound=true;bankDialog=false;notify('演示银行卡已绑定')">使用这张演示卡</el-button></template></el-dialog></div></template>
<style scoped>.wallet-banner{height:170px;background:#002bd7;color:white;border-radius:9px;position:relative;overflow:hidden;display:flex;gap:35px;align-items:center;padding:30px 35px;margin-bottom:25px}.wallet-banner>img{position:absolute;right:0;top:0;height:100%;width:27%;object-fit:cover;object-position:right;opacity:.9}.wallet-banner>div,.wallet-banner>.el-button{position:relative;z-index:1}.wallet-banner>div>span{font-size:14px;display:block}.wallet-banner strong{font-size:30px;display:block;font-variant-numeric:tabular-nums;margin-top:10px}.wallet-banner strong.wallet-amount{font-size:47px}.wallet-banner>div:nth-last-child(2){border-left:1px solid #ffffff50;padding-left:35px}.wallet-columns{grid-template-columns:minmax(0,1.5fr) minmax(300px,1fr)}@media(max-width:1200px){.wallet-banner{padding:24px;gap:24px}.wallet-banner strong.wallet-amount{font-size:35px}.wallet-banner strong{font-size:24px}.wallet-banner>div:nth-last-child(2){padding-left:24px}.wallet-columns{grid-template-columns:1fr}}@media(max-width:650px){.wallet-banner{height:auto;padding:22px;display:grid;grid-template-columns:1fr 1fr;gap:15px}.wallet-banner>div:nth-last-child(2){border:0;padding:0}.wallet-banner strong.wallet-amount{font-size:30px}.wallet-banner strong{font-size:20px}.wallet-banner>div>span{font-size:12px}.wallet-banner>img{width:50%}}</style>
